21	export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
22	  route,
23	  navigation,
24	}) => {
25	  const { roomId } = route.params;
26	  const client = MatrixCore.instance;
27	  const room = useMemo(() => client?.getRoom(roomId), [client, roomId]);
28	  const insets = useSafeAreaInsets();
29	  const roomInfo = useRoomInfo(room);
30	  const isFocused = useIsFocused();
31	  const [isInviteAccepted, setIsInviteAccepted] = useState(false);
32	  const initialMembershipRef = useRef<Membership | null>(null);
33	  const isOffline = useAtomValue(NetworkAtoms.isOffline);
34	  const isRoomInvite = useMemo(() => {
35	    return roomInfo?.membership === Membership.Invited && !isInviteAccepted;
36	  }, [roomInfo, isInviteAccepted]);
37	  const isBanned = roomInfo?.membership === Membership.Banned;
38	  const isKicked = roomInfo?.membership === Membership.Knocked;
39	  const hasOngoingRoomCall = roomInfo?.hasRoomCall ?? false;
40	  const hasActiveCall = useAtomValue(CallAtoms.hasActiveCall);
41	  const hasPowerLevelToCall =
42	    roomInfo?.powerLevels?.canOwnUserSendState(StateEventType.CallMember) ??
43	    false;
44	
45	  const {
46	    members,
47	    isLoading: isMembersLoading,
48	    fetchMembers,
49	  } = useRoomMembers(room);
50	  const roomMembers = useMemo(
51	    () =>
52	      members.filter((m) => m.membership?.tag === MembershipState_Tags.Join)
53	        .length,
54	    [members],
55	  );
56	
57	  useEffect(() => {
58	    if (!roomInfo) return;
59	
60	    // Record the first known membership so we can detect changes
61	    if (initialMembershipRef.current === null) {
62	      initialMembershipRef.current = roomInfo.membership;
63	      return;
64	    }
65	
66	    // If membership changed to Left while on screen, the user was kicked
67	    if (
68	      roomInfo.membership === Membership.Left &&
69	      initialMembershipRef.current !== Membership.Left
70	    ) {
71	      navigation.goBack();
72	    }
73	  }, [roomInfo?.membership]);
74	
75	  const handleStartCall = () => {
76	    if (!client || !room) {
77	      console.error("Client or room not available");
78	      return;
79	    }
80	
81	    if (hasActiveCall) {
82	      offlineToastHelper("You are already in a call");
83	      return;
84	    }
85	
86	    if (isOffline) {
87	      offlineToastHelper("No internet connection");
88	      return;
89	    }
90	
91	    CallOverlayService.openCall(roomId, room.displayName());
92	  };
93	
94	  const handleInviteAccepted = () => {
95	    setIsInviteAccepted(true);
96	  };
97	
98	  const handleInviteDeclined = () => {
99	    navigation.goBack();
100	  };
101	
102	  const handleRoomDetails = () => {
103	    if (isRoomInvite || !room) return;
104	    navigation.navigate("roomDetails", { room });
105	  };
106	
107	  useEffect(() => {
108	    if (!isFocused) return;
109	    fetchMembers();
110	  }, [isFocused, fetchMembers]);
111	
112	  if (!room) return null;
113	
114	  if (!roomInfo) {
115	    return (
116	      <Screen hideTopSafeArea scrollable={false}>
117	        <RoomHeader
118	          room={room}
119	          isMembersLoading={isMembersLoading}
120	          roomMembers={roomMembers}
121	          hasCallOption
122	          topInset={insets.top}
123	          onBack={() => navigation.goBack()}
124	        />
125	        <Loading isFullScreen={false} />
126	      </Screen>
127	    );
128	  }
129	
130	  return (
131	    <Screen hideTopSafeArea>
132	      <RoomHeader
133	        room={room}
134	        isDirect={!!roomInfo.isDirect}
135	        isMembersLoading={isMembersLoading}
136	        roomMembers={roomMembers}
137	        hasCallOption={!isRoomInvite && !isBanned && hasPowerLevelToCall}
138	        hasOngoingRoomCall={hasOngoingRoomCall}
139	        hasActiveCall={hasActiveCall}
140	        topInset={insets.top}
141	        onBack={() => navigation.goBack()}
142	        onRoomDetails={handleRoomDetails}
143	        onStartCall={handleStartCall}
144	      />
145	
146	      {isBanned || isKicked ? (
147	        <RoomBanned
148	          type={isBanned ? "banned" : "kicked"}
149	          room={room}
150	          onForgotten={() => navigation.goBack()}
151	        />
152	      ) : isRoomInvite ? (
153	        <RoomInvite
154	          roomId={roomId}
155	          roomInfo={roomInfo}
156	          memberCount={roomMembers}
157	          onAccepted={handleInviteAccepted}
158	          onDeclined={handleInviteDeclined}
159	        />
160	      ) : (
161	        <RoomTimeline room={room} roomId={roomId} />
162	      )}
163	    </Screen>
164	  );
165	};
