43	    <Screen
44	      hideBottomSafeArea
45	      hideTopSafeArea
46	      background={background}
47	      scrollable={scrollable}
48	      paddings={Object.assign({}, verticalPaddings, paddings)}
49	    >
50	      {type === "modal" && (
51	        <Block
52	          paddings={{ paddingTop: 12, paddingBottom: 40 }}
53	          background="transparent"
54	          align="center"
55	          justify="center"
56	        >
